<?php require_once 'config/auth.php'; require_login(); $pageTitle='Inventario';
$q=trim($_GET['q']??''); $estado=$_GET['estado']??'';
$sql="SELECT p.*,c.nombre categoria FROM producto p JOIN categoria c ON c.id_categoria=p.id_categoria WHERE p.estado=1"; $params=[];
if($q!==''){ $sql.=' AND (p.nombre LIKE ? OR p.codigo LIKE ?)'; $params=["%$q%","%$q%"];} if($estado==='bajo') $sql.=' AND p.stock_actual<=p.stock_minimo'; $sql.=' ORDER BY p.nombre'; $st=$pdo->prepare($sql);$st->execute($params);$rows=$st->fetchAll(); require 'partials/header.php'; ?>
<div class="page-head"><div><span class="eyebrow">CONSULTA</span><h1>Inventario</h1><p>Estado actual de productos y niveles mínimos.</p></div><?php if(($user['rol']??'')==='propietario'):?><a class="btn primary" href="productos.php">Gestionar productos</a><?php endif;?></div>
<form class="filter" method="get"><input name="q" value="<?=e($q)?>" placeholder="Buscar por nombre o código"><select name="estado"><option value="">Todos</option><option value="bajo" <?=$estado==='bajo'?'selected':''?>>Solo bajo stock</option></select><button class="btn primary">Filtrar</button><a class="btn ghost" href="inventario.php">Limpiar</a></form>
<div class="panel"><div class="table-wrap"><table><thead><tr><th>Código</th><th>Producto</th><th>Categoría</th><th>Unidad</th><th>Stock</th><th>Mínimo</th><th>Estado</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><code><?=e($r['codigo'])?></code></td><td><b><?=e($r['nombre'])?></b></td><td><?=e($r['categoria'])?></td><td><?=e($r['unidad'])?></td><td><strong><?=e((string)$r['stock_actual'])?></strong></td><td><?=e((string)$r['stock_minimo'])?></td><td><?=$r['stock_actual']<=$r['stock_minimo']?'<span class="badge danger">Bajo</span>':'<span class="badge success">Normal</span>'?></td></tr><?php endforeach;?></tbody></table></div><?php if(!$rows):?><div class="empty">No se encontraron productos.</div><?php endif;?></div>
<?php require 'partials/footer.php'; ?>
